input.function:
() => {
  const out = {};
  out.font = document.fonts.check('700 51px Inter');
  const card = document.getElementById('card');
  const cr = card.getBoundingClientRect();
  out.card = [cr.width, cr.height];
  const inner = card.querySelector('.inner');
  out.innerOverflow = inner.scrollHeight - inner.clientHeight;
  const boxes = [];
  card.querySelectorAll('.header,.portrait,.name,.role,.kicker,.title,.meta,.cta,.footer,.speaker').forEach(el=>{
    const r = el.getBoundingClientRect();
    boxes.push({c: el.className, t: Math.round(r.top), b: Math.round(r.bottom), l: Math.round(r.left), r: Math.round(r.right), lines: Math.round(r.height / parseFloat(getComputedStyle(el).lineHeight||1))});
  });
  out.boxes = boxes;
  // text clipping check
  out.clipped = [...card.querySelectorAll('*')].filter(e=>e.scrollWidth>e.clientWidth+1||e.scrollHeight>e.clientHeight+1).map(e=>e.className+':'+e.scrollWidth+'/'+e.clientWidth+' '+e.scrollHeight+'/'+e.clientHeight);
  const p = card.querySelector('.portrait').getBoundingClientRect();
  out.portraitSquare = [Math.round(p.width), Math.round(p.height)];
  return out;
}

